// file.stat: reports what is at a path on the target and changes nothing.
package file

import (
	"context"
	"fmt"
	"sort"

	"github.com/Subject-Void-LLC/the-pleiades/pkg/capability"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/collection"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/inventory"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/remotefile"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/sdk"
)

// This file implements "file.stat", generated by
// pleiades forge new-collection and then hand-completed.
//
// It is ansible.builtin.stat for what the file methods already read: one
// remotefile.Stat, reported under the keys remotefile.Info.Map writes,
// which are the words every file method's diff uses. It exists so an
// agent or a runbook can look at a path without a shell command, which
// reports changed on every run (it cannot tell what its command did) and
// so leaves a run behind that a later rollback has to step over.

// statParamPath is the one parameter, ansible.builtin.stat's own name.
const statParamPath = "path"

func init() {
	collection.MustRegister(collection.Descriptor{
		Name: "file.stat",
		Manifest: collection.Manifest{
			SupportedTransports:  []string{"ssh"},
			RequiredCapabilities: []capability.Name{capability.NamePOSIXFileSystem},
			ExecutionContext: collection.ExecutionContext{
				RequiresElevation: false,
				Site:              collection.SiteTarget,
				Device:            collection.DeviceRequired,
			},
			PlatformTargets: nil,
			EngineVersion:   ">=0.2.0",
			Status:          collection.StatusImplemented,
			Reversibility: collection.Reversibility{
				ReadOnly: true,
				Notes:    "It only reads what is at a path; nothing on the device changes, so there is nothing to undo.",
			},
			// It only reads, so its check is the same read.
			SupportsCheck: true,
			Doc: collection.Doc{
				Summary:     "Reports what is at a path on the target, and changes nothing.",
				Description: "Reads what is at a path and reports it: whether anything is there, what it is (a file, a directory, a symlink or something else), its mode, owner and group, a symlink's target, its size and its modification time. This is ansible.builtin.stat. It only reads, so it never reports a change, records no undo, and its check is the same read. An absent path is an answer (exists is false), not a failure. Use it to look at a path before or after a change instead of a shell command, which reports changed on every run because it cannot tell what its command did.",
				Params: []collection.Param{
					{Name: "path", Type: "string", Required: true, Description: "The path to look at. A symlink is reported as the link itself, with its target, not as what it points to."},
					{Name: "insecure_skip_host_key_verify", Type: "bool", Default: "false", Description: "Skip SSH host key verification for this task. This removes protection against a machine in the middle answering for the device, so set it only for a target you have decided does not need it."},
				},
				Returns: []collection.ReturnField{
					{Name: "path", Type: "string", Returned: "always", Description: "The path this task looked at."},
					{Name: "exists", Type: "bool", Returned: "always", Description: "Whether anything is at the path."},
					{Name: "kind", Type: "string", Returned: "always", Description: "What is there: file, directory, symlink, other, or absent."},
					{Name: "mode", Type: "string", Returned: "when it exists", Description: "The permission bits in octal, such as 0755, with the setuid, setgid and sticky digit when one is set."},
					{Name: "owner", Type: "string", Returned: "when it exists", Description: "The owning user's name."},
					{Name: "group", Type: "string", Returned: "when it exists", Description: "The owning group's name."},
					{Name: "size", Type: "int", Returned: "when it exists", Description: "The size in bytes."},
					{Name: "mtime", Type: "int", Returned: "when it exists", Description: "The modification time, as a Unix timestamp."},
					{Name: "target", Type: "string", Returned: "when it is a symlink", Description: "Where the symlink points."},
				},
				Examples: []collection.Example{
					{Name: "Look at a directory before changing it", RunbookYAML: "- name: See what is at the app directory\n  file.stat:\n    path: /srv/app\n  register: app_dir\n"},
				},
				SeeAlso: []string{"file.directory", "file.permissions", "facts.gather"},
			},
		},
		Invoke: Stat,
		Check:  Stat,
	})
}

// Stat implements "file.stat": it reads what is at path and records it,
// key by key in name order, beside the path itself. It changes nothing
// and reports no change, so a check is the same call.
func Stat(ctx context.Context, rc sdk.RunbookContext, device inventory.InventoryItem, params map[string]any) (collection.Result, error) {
	const fqcn = "file.stat"
	path, err := sdk.RequiredStringParam(params, statParamPath)
	if err != nil {
		return collection.Result{}, fmt.Errorf("%s: %w", fqcn, err)
	}
	conn, err := sdk.Connect(ctx, rc, device, params, fqcn)
	if err != nil {
		return collection.Result{}, err
	}
	defer func() { _ = conn.Close() }()

	info, err := remotefile.Stat(ctx, conn, path)
	if err != nil {
		return collection.Result{}, fmt.Errorf("%s: %w", fqcn, err)
	}
	stats := info.Map()
	stats[statParamPath] = path
	keys := make([]string, 0, len(stats))
	for key := range stats {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	for _, key := range keys {
		if err := rc.SetStat(key, stats[key]); err != nil {
			return collection.Result{}, fmt.Errorf("%s: %w", fqcn, err)
		}
	}
	return collection.Result{}, nil
}
